create extension if not exists pgcrypto;
create table if not exists public.products (
 id text primary key, slug text unique not null, name_en text not null, name_ar text not null default '', description_en text not null default '', description_ar text not null default '', price integer not null check (price >= 0), compare_at_price integer, category text not null, collection text not null default 'Y JOEX', gender text not null default 'unisex', colors text[] not null default '{}', sizes text[] not null default '{}', stock jsonb not null default '{}', images text[] not null default '{}', featured boolean not null default false, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.orders (
 id uuid primary key default gen_random_uuid(), order_number text unique not null, customer_name text not null, phone text not null, governorate text not null, city text not null, address text not null, notes text, items jsonb not null, subtotal integer not null, shipping integer not null, total integer not null, status text not null default 'new' check(status in ('new','confirmed','shipped','delivered','cancelled')), created_at timestamptz not null default now()
);
create table if not exists public.shipping_fees (governorate text primary key, fee integer not null default 100);
create table if not exists public.site_settings (key text primary key, value jsonb not null default '{}');
on conflict(governorate) do nothing;
on conflict (id) do nothing;
